def dyadicSelectedCell (e : DyadicSubtreeEmbedding) (s : DyadicTreeNode) : Finset DyadicTreeNode :=
  match s.reverse with
  | [] => {e []}
  | b :: r => dyadicTreeInterval (e r.reverse ++ [b]) (e s)

